contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function driven by inputs
    function run(address newOwner) public payable {
        // read the owner before calling
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // only the contract itself (this) is the deployer/owner of c in the checker setup,
        // so calls here originate from this test contract and thus are from the current owner.
        bool succeeded;
        bool returnedTrue = false;

        // call setOwner and capture whether it reverted and its return value
        bool ok = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            succeeded = false;
        } else {
            succeeded = true;
            returnedTrue = ok;
        }

        // read owner after attempting the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General property: when the current owner calls setOwner it must succeed (not revert),
        // must return true, and owner must equal the provided newOwner afterwards.
        // Because this test contract is the deployer of c, msg.sender==ownerBefore here.
        assert(succeeded && returnedTrue && ownerAfter == newOwner);
    }

    receive() external payable { }
}

